    std::string s;
    std::cin >> s;
    // Convert string to lowercase
    std::transform(s.begin(), s.end(), s.begin(), ::tolower);
    int maxL = -1;
    int nwi = 0;
    int fp = 0;
    int fw = 0;
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (c == '(') {
            fp++;
            fw = 0;
        } else if (c == ')') {
            if (fp == 1 && fw != 0) nwi++;
            fp--;
            fw = 0;
        } else if (c == '_') {
            if (fp == 1 && fw != 0) nwi++;
            fw = 0;
        } else {
            fw++;
        }
        if (fp == 0) maxL = std::max(fw, maxL);
    }
    std::cout << maxL << " " << nwi << std::endl;
    return 0;
}
